    var quick = COLORS.map(function (c, i) { return "<button type='button' class='a-IRR-highlightQuickPick a-IRR-highlightQuickPick--" + (i + 1) + "' data-bg='" + c[0] + "' style='background:" + c[0] + "' aria-label='" + c[0] + "' title='" + c[0] + "'></button>"; }).join("");
